// Krastor — color emoji glyph atlas.
// Loads data/fonts/emoji_atlas.png (generated by tools/gen_emoji_atlas.py
// from Noto Color Emoji CBDT bitmaps) into one GL_RGBA texture plus a
// codepoint -> UV-rect map from emoji_atlas.json. The chat renderer draws
// emoji tokens as nk_draw_image quads; the glfw backend binds the texture
// per draw command, so no backend patch is needed.

#pragma once

#include <cstdint>
#include <string>
#include <unordered_map>

namespace krastor {

class EmojiAtlas {
public:
    struct Rect {
        int x, y, w, h;  // glyph cell in atlas pixel coords (nk_image region)
    };

    // Loads png_path + json_path (manifest from the generator). Uploads the
    // GL texture — must be called with a current GL context. Returns false
    // (ok() == false) when either file is missing; the app then renders
    // emoji as '?' like before.
    bool load(const std::string& png_path, const std::string& json_path);
    // exe_dir()/data/fonts, then ./data/fonts.
    bool load_default();

    // UV rect for a codepoint (U+FE0F is stripped by the caller), or nullptr.
    const Rect* find(char32_t cp) const;

    bool ok() const { return ok_; }
    unsigned texture() const { return tex_; }
    int tex_w() const { return tex_w_; }
    int tex_h() const { return tex_h_; }

private:
    std::unordered_map<char32_t, Rect> rects_;
    unsigned tex_ = 0;
    int tex_w_ = 0, tex_h_ = 0;
    bool ok_ = false;
};

} // namespace krastor
